#define PIR_PIN 27
#define LED_HIJAU 25
#define LED_KUNING 26
#define LED_MERAH 33
#define BUZZER 32

unsigned long waktuDeteksi = 0;
bool gerakan = false;

void setup() {
  Serial.begin(115200);

  pinMode(PIR_PIN, INPUT);
  pinMode(LED_HIJAU, OUTPUT);
  pinMode(LED_KUNING, OUTPUT);
  pinMode(LED_MERAH, OUTPUT);
  pinMode(BUZZER, OUTPUT);

  digitalWrite(LED_HIJAU, HIGH);
}

void loop() {
  int nilaiPIR = digitalRead(PIR_PIN);

  if (nilaiPIR == HIGH) {

    if (!gerakan) {
      waktuDeteksi = millis();
      gerakan = true;
      Serial.println("Gerakan Terdeteksi");
    }

    digitalWrite(LED_HIJAU, LOW);
    digitalWrite(LED_KUNING, HIGH);

    unsigned long durasi = millis() - waktuDeteksi;

    if (durasi > 5000) {
      digitalWrite(LED_MERAH, HIGH);
      tone(BUZZER, 1000);
      Serial.println("ALARM AKTIF");
    }

  } else {

    gerakan = false;

    digitalWrite(LED_HIJAU, HIGH);
    digitalWrite(LED_KUNING, LOW);
    digitalWrite(LED_MERAH, LOW);

    noTone(BUZZER);
  }

  delay(100);
}
